import{_ as e,o,c as r,a2 as t}from"./chunks/framework.yo2CxoV2.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1794339637000}'),n={name:"troubleshooting.md"};function d(i,a,h,l,c,s){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="看不到业务模型" tabindex="-1">看不到业务模型 <a class="header-anchor" href="#看不到业务模型" aria-label="Permalink to &quot;看不到业务模型&quot;">​</a></h2><p>确认模型已注册到 Django Admin，业务应用已加入 <code>INSTALLED_APPS</code>，当前账号拥有对应模块和模型权限。再检查 <code>get_queryset()</code> 或自定义菜单是否缩小了范围。</p><p>只有新增权限时看到录入页属于预期行为，不会同时开放列表与详情。</p><h2 id="页面仍显示历史品牌" tabindex="-1">页面仍显示历史品牌 <a class="header-anchor" href="#页面仍显示历史品牌" aria-label="Permalink to &quot;页面仍显示历史品牌&quot;">​</a></h2><p>确认安装的是 <code>ordloom==1.0.0</code>，并检查部署后的包版本及静态文件。项目自己的站点标题通过 <code>ORDLOOM_SITE_TITLE</code> 配置，见 <a href="./reference/compatibility.html">环境与接入</a>。</p><p>源码版本更新后，重建前端、同步包内静态资源，再重新部署与收集静态文件。不要只修改浏览器标题却遗漏登录页、页脚或演示资源。</p><h2 id="写入返回-403-或-csrf-错误" tabindex="-1">写入返回 403 或 CSRF 错误 <a class="header-anchor" href="#写入返回-403-或-csrf-错误" aria-label="Permalink to &quot;写入返回 403 或 CSRF 错误&quot;">​</a></h2><p>检查当前会话、账号资格、对象权限以及最新的 CSRF 信息。登录会轮换令牌；HttpOnly 或会话 CSRF 不能只通过 <code>document.cookie</code> 读取。内置客户端会处理这些情况。</p><h2 id="编辑器内容没有保存" tabindex="-1">编辑器内容没有保存 <a class="header-anchor" href="#编辑器内容没有保存" aria-label="Permalink to &quot;编辑器内容没有保存&quot;">​</a></h2><p>自定义包装控件应转发 <code>value/onChange/id</code>。确认没有把注册逻辑放入重复执行的轻量入口。保存失败时还需查看具体字段、明细或跨字段校验，而不是只检查编辑器是否有文字。</p><h2 id="上传按钮不可用或上传失败" tabindex="-1">上传按钮不可用或上传失败 <a class="header-anchor" href="#上传按钮不可用或上传失败" aria-label="Permalink to &quot;上传按钮不可用或上传失败&quot;">​</a></h2><p>独立前端演示没有连接 Django 时，上传入口不可用。真实项目还会检查字段格式、大小、图片实际内容、对象和 inline 权限、动态只读规则以及 storage 返回的地址。</p><p>若上传成功但图片不能显示，检查媒体服务、地址编码、签名链接有效期及跨域访问。上传后再次保存不应手工把 URL 编码成另一层存储名。</p><h2 id="json-大整数变化" tabindex="-1">JSON 大整数变化 <a class="header-anchor" href="#json-大整数变化" aria-label="Permalink to &quot;JSON 大整数变化&quot;">​</a></h2><p>使用接口提供的精确文本来源，不要先转为 JavaScript Number。格式化与压缩应只改变空白。具体说明见<a href="./components/json.html">JSON 编辑器</a>。</p><h2 id="markdown-预览一直加载或报-worker-错误" tabindex="-1">Markdown 预览一直加载或报 Worker 错误 <a class="header-anchor" href="#markdown-预览一直加载或报-worker-错误" aria-label="Permalink to &quot;Markdown 预览一直加载或报 Worker 错误&quot;">​</a></h2><p>先检查原文是否仍可编辑，再检查构建产物、Worker 地址、MIME、CSP、CORS 和网络错误；预览失败可重试。跨域静态部署尤其需要核对 Worker 加载策略。</p><h2 id="没有进入原生-admin-编辑页" tabindex="-1">没有进入原生 Admin 编辑页 <a class="header-anchor" href="#没有进入原生-admin-编辑页" aria-label="Permalink to &quot;没有进入原生 Admin 编辑页&quot;">​</a></h2><p>默认完全接管挂载点下管理页面。需要原生兜底时使用 <code>ORDLOOM_FULL_TAKEOVER = False</code>，或将两套入口挂在不同路径。</p><h2 id="地图空白" tabindex="-1">地图空白 <a class="header-anchor" href="#地图空白" aria-label="Permalink to &quot;地图空白&quot;">​</a></h2><p>先判断坐标控件是否正常。默认底图依赖外部瓦片服务；不可达时可以继续填写经纬度，或配置自己的 <code>tile_url</code>。当前没有 POI 搜索功能。</p><h2 id="文档和安装后的界面不完全相同" tabindex="-1">文档和安装后的界面不完全相同 <a class="header-anchor" href="#文档和安装后的界面不完全相同" aria-label="Permalink to &quot;文档和安装后的界面不完全相同&quot;">​</a></h2><p>确认查看的是当前发行版能力还是<a href="./appendix/design.html">设计概念图</a>。遇到问题可在<a href="https://github.com/neekin/ordloom-docs/issues" target="_blank" rel="noreferrer">文档仓库</a>提供包版本、Django/Python 版本、复现步骤与已脱敏的错误信息。</p>',24)])])}const m=e(n,[["render",d]]);export{u as __pageData,m as default};
